const body = $('SNS webhook').first().json.body;
const ALIAS = { instagram: 'instagram', insta: 'instagram', '인스타': 'instagram', '인스타그램': 'instagram',
  x: 'x', twitter: 'x', '트위터': 'x', '엑스': 'x', linkedin: 'linkedin', '링크드인': 'linkedin' };
const asked = Array.isArray(body.channels) ? body.channels : [];
let channels = [...new Set(asked.map(c => ALIAS[String(c).trim().toLowerCase()]).filter(Boolean))];
const unknown = asked.filter(c => !ALIAS[String(c).trim().toLowerCase()]).map(String);
if (!channels.length) channels = ['instagram', 'x'];
return [{ json: { text: String(body.text).trim(), channels, unknown } }];

function parseJson(output) {
  const raw = String(output ?? '');
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start < 0 || end < start) throw new Error('no JSON');
  return JSON.parse(raw.slice(start, end + 1));
}
const prep = $('Prepare posts').first().json;
const LIMIT = { instagram: { max: 300, tags: 5 }, x: { max: 140, tags: 2 }, linkedin: { max: 400, tags: 3 } };
const digits = s => [...String(s).matchAll(/\d[\d,.]*/g)].map(m => m[0].replace(/[,.]/g, ''));
const sourceNumbers = new Set(digits(prep.text));
let posts = [];
try { posts = parseJson($json.output).posts || []; } catch (error) { posts = []; }
// 글자 수 · 해시태그 수는 LLM이 아니라 여기서 지킨다
const fit = (body, tags, max) => {
  const tagText = tags.length ? ' ' + tags.join(' ') : '';
  if ((body + tagText).length <= max) return body + tagText;
  const sentences = body.match(/[^.!?。]+[.!?。]?/g) || [body];
  let out = '';
  for (const s of sentences) { if ((out + s).trim().length + tagText.length > max) break; out += s; }
  out = out.trim() || body.slice(0, Math.max(0, max - tagText.length - 1)).trim() + '…';
  return (out + tagText).slice(0, max);
};
const result = prep.channels.map(channel => {
  const found = posts.find(p => p && String(p.channel).toLowerCase() === channel);
  let raw = String(found?.text ?? '').trim();
  const ok = raw && digits(raw).every(n => sourceNumbers.has(n));
  if (!ok) raw = prep.text;  // 지어낸 숫자가 있거나 빈 글이면 원문에서 줄인다
  const tags = [...new Set(raw.match(/#[^\s#]+/g) || [])].slice(0, LIMIT[channel].tags);
  const body = raw.replace(/#[^\s#]+/g, '').replace(/\s+/g, ' ').trim();
  const text = fit(body, tags, LIMIT[channel].max);
  return { channel, text, length: text.length, limit: LIMIT[channel].max, source: ok ? 'llm' : 'original' };
});
const skipped = prep.unknown.length ? ` (지원하지 않는 채널 제외: ${prep.unknown.join(', ')})` : '';
return [{ json: { route: '자동 답변', posts: result, answer: result.map(p => `[${p.channel} ${p.length}/${p.limit}자] ${p.text}`).join('\n') + skipped } }];
